import json, math
import numpy as np

PATH = '/data/wuchenmin/Project/ToolKG/SciToolFlow/.local/experiment_sources/scimas_ablation_20261107_105210_mini100_50/tasks/mini-100/assets/study_FLOW-0387.json'
fh = open(PATH)
doc = json.load(fh)
fh.close()

def walk(o, acc):
    acc.append(o)
    if isinstance(o, dict):
        for v in o.values():
            walk(v, acc)
    elif isinstance(o, list):
        for v in o:
            walk(v, acc)

alld = []
walk(doc, alld)

def isnum(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

Xraw = None
rec = None
fkey = None
for o in alld:
    if isinstance(o, dict):
        for k in ('observed_features', 'features', 'X', 'Xmat', 'design_matrix'):
            v = o.get(k)
            if isinstance(v, list) and len(v) > 0 and isinstance(v[0], list) and len(v[0]) > 0 and all(isnum(x) for x in v[0]):
                rec = o
                Xraw = v
                fkey = k
                break
    if rec is not None:
        break

assert rec is not None, 'feature matrix not found'
Xall = [[float(x) for x in row] for row in Xraw]
n = len(Xall)
p = len(Xall[0])

def rowvec(v):
    return isinstance(v, list) and len(v) == n and all(isnum(x) for x in v)

tidx = None
tname = None
for o in alld:
    if isinstance(o, dict):
        for k in ('target_index', 'target_col', 'target_column_index', 'response_index', 'outcome_index'):
            if k in o and isinstance(o[k], int) and not isinstance(o[k], bool):
                tidx = o[k]
        for k in ('target_column', 'target_name', 'response_column', 'outcome_column'):
            if k in o and isinstance(o[k], str) and isinstance(o.get('columns'), list) and o[k] in o['columns']:
                tname = o[k]
if tname is not None and isinstance(rec.get('columns'), list):
    tidx = rec['columns'].index(tname)
if tidx is not None and (tidx < 0 or tidx >= p):
    tidx = None

nominal = None
for o in alld:
    if isinstance(o, dict):
        for k, v in o.items():
            kl = k.lower()
            if isnum(v):
                fv = float(v)
                if 0.5 <= fv < 1.0 and ('nominal' in kl or 'coverage' in kl or 'confidence' in kl or 'level' in kl):
                    if nominal is None:
                        nominal = fv
                if 0.0 < fv < 0.5 and ('alpha' in kl or 'miscoverage' in kl or 'significance' in kl):
                    if nominal is None:
                        nominal = 1.0 - fv
if nominal is None:
    nominal = 0.9

yt = None
if tidx is None:
    for k, v in rec.items():
        if k == fkey or k in ('case_id', 'columns', 'role', 'roles', 'cases'):
            continue
        if rowvec(v):
            yt = [float(x) for x in v]
            break

if tidx is not None:
    y = [Xall[i][tidx] for i in range(n)]
    fcols = [j for j in range(p) if j != tidx]
elif yt is not None:
    y = yt
    fcols = list(range(p))
else:
    y = [Xall[i][p - 1] for i in range(n)]
    fcols = list(range(p - 1))

X = [[Xall[i][j] for j in fcols] for i in range(n)]

roles = None
for o in alld:
    if isinstance(o, dict):
        for k, v in o.items():
            if isinstance(v, list) and len(v) == n and all(isinstance(x, str) for x in v):
                low = [x.lower() for x in v]
                if all(any(t in s for t in ('train', 'calib', 'assess', 'final', 'test', 'hold', 'fit')) for s in low):
                    roles = low
                    break
    if roles is not None:
        break

def find_idx(names):
    for o in alld:
        if isinstance(o, dict):
            for k, v in o.items():
                kl = k.lower()
                if isinstance(v, list) and len(v) > 0 and all(isinstance(x, int) and not isinstance(x, bool) for x in v):
                    for nm in names:
                        if nm in kl:
                            return v
    return None

tr = ca = as_ = None
if roles is not None:
    tr = [i for i in range(n) if 'train' in roles[i] or roles[i] == 'fit']
    ca = [i for i in range(n) if 'calib' in roles[i]]
    as_ = [i for i in range(n) if ('assess' in roles[i] or 'final' in roles[i] or 'hold' in roles[i] or roles[i].startswith('test'))]
if not (tr and ca and as_):
    dt = None
    for o in alld:
        if isinstance(o, dict):
            got = {}
            for k, v in o.items():
                if isinstance(v, dict):
                    for k2, v2 in v.items():
                        if isinstance(v2, list) and len(v2) > 0 and all(isinstance(x, int) and not isinstance(x, bool) for x in v2):
                            kl = k2.lower()
                            if 'train' in kl:
                                got['t'] = v2
                            elif 'calib' in kl:
                                got['c'] = v2
                            elif 'assess' in kl or 'final' in kl or 'test' in kl or 'hold' in kl:
                                got['a'] = v2
            if 't' in got and 'c' in got and 'a' in got:
                dt = got
                break
    if dt is not None:
        tr, ca, as_ = dt['t'], dt['c'], dt['a']
if not (tr and ca and as_):
    ti = find_idx(['training', 'train_idx', 'train_index', 'train_indices', 'fit_idx'])
    ci = find_idx(['calibration', 'calib', 'cal_idx', 'cal_index', 'cal_indices'])
    ai = find_idx(['assessment', 'assess', 'final', 'test', 'holdout', 'hold_out', 'assess_idx', 'test_idx'])
    if ti and ci and ai:
        tr, ca, as_ = ti, ci, ai

if not (tr and ca and as_):
    fr = {}
    for o in alld:
        if isinstance(o, dict):
            for k, v in o.items():
                kl = k.lower()
                if isnum(v) and 0.0 < float(v) < 1.0:
                    if 'train' in kl and ('frac' in kl or 'prop' in kl or 'size' in kl):
                        fr['t'] = float(v)
                    elif 'calib' in kl and ('frac' in kl or 'prop' in kl or 'size' in kl):
                        fr['c'] = float(v)
                    elif ('assess' in kl or 'final' in kl or 'test' in kl) and ('frac' in kl or 'prop' in kl or 'size' in kl):
                        fr['a'] = float(v)
    ft = fr.get('t', 0.6)
    fc = fr.get('c', 0.2)
    nt = int(round(ft * n))
    nc = int(round(fc * n))
    tr = list(range(0, nt))
    ca = list(range(nt, nt + nc))
    as_ = list(range(nt + nc, n))

Xtr = np.array([X[i] for i in tr], float)
ytr = np.array([y[i] for i in tr], float)
A = np.column_stack([np.ones(len(tr)), Xtr])
beta, _, _, _ = np.linalg.lstsq(A, ytr, rcond=None)

Xca = np.array([X[i] for i in ca], float)
Aca = np.column_stack([np.ones(len(ca)), Xca])
pcal = Aca.dot(beta)
cal_res = np.abs(np.array([y[i] for i in ca], float) - pcal)
ns = len(cal_res)
k = int(math.ceil((ns + 1) * nominal))
if k < 1:
    k = 1
srt = np.sort(cal_res)
if k > ns:
    radius = float(srt[-1])
else:
    radius = float(srt[k - 1])
width = 2.0 * radius

Xas = np.array([X[i] for i in as_], float)
Aas = np.column_stack([np.ones(len(as_)), Xas])
pas = Aas.dot(beta)
ass_res = np.abs(np.array([y[i] for i in as_], float) - pas)
covered = int(np.sum(ass_res <= radius + 1e-12))
na = len(ass_res)
coverage = float(covered) / na if na > 0 else float('nan')
reaches = bool(coverage >= nominal - 1e-12)

out = {
    'calibration_order_rank': int(k),
    'calibrated_radius': float(radius),
    'common_interval_width': float(width),
    'assessment_covered_rows': int(covered),
    'assessment_empirical_coverage': float(coverage),
    'empirical_coverage_reaches_nominal': bool(reaches),
    'nominal_coverage': float(nominal),
    'n_training': len(tr),
    'n_calibration': ns,
    'n_assessment': na,
    'limitation': 'Finite-sample split-conformal coverage audit on archived observations; model fitting, interval calibration, and final assessment use disjoint predeclared roles; coverage is marginal over the assessment set and is not an individual guarantee or clinical guidance.'
}
print(json.dumps(out))

